def norm(dt):
    return dt[:19] + "Z"

out = []
for subj, s, e, showas, allday, cancelled, att, cats in E:
    out.append({
        "subject": subj if subj is not None else "",
        "start": norm(s),
        "end": norm(e),
        "showAs": showas,
        "isAllDay": allday,
        "isCancelled": cancelled,
        "attendees": att if att is not None else [],
        "categories": cats,
    })

with open("/home/user/austin-proper-gm-report/calendar_raw_14d.json","w") as f:
    json.dump(out, f, indent=2)

print("written:", len(out))

# Analysis
from collections import defaultdict
from datetime import datetime, timedelta
timed_busy = [o for o in out if not o["isAllDay"] and o["showAs"] in ("busy","tentative")]
print("timed busy/tentative:", len(timed_busy))
dates = set()
for o in out:
    if not o["isAllDay"] and o["showAs"] == "busy":
        dt = datetime.strptime(o["start"][:19], "%Y-%m-%dT%H:%M:%S")
        local = dt - timedelta(hours=5)
        dates.add(local.strftime("%Y-%m-%d"))
print("dates with timed busy:", sorted(dates))
